#!/usr/bin/env python3
"""simcompare 단일 파일 실행기 (자동 생성: scripts/build_single_file.py). 소스 해시 8b8b66d5a74ee0d700f6d670ffe1f3cefe7e1f36993323185336fc4cc6d6a248.
서버 wrapper가 명령줄 인자를 넘기지 못할 때 쓴다. 아래 EDIT 블록만 고치고 이 파일을 그대로 실행한다."""
# 6회차: 대응 쌍 위치의 창별 국부 ΔCA. 기본 입력은 4회차의 직접 대응 data/changes/direct/roi_correspondence.json이다.
# DL2 경로(5회차)를 쓴 경우에는 --correspondence를 data/confirmed/roi_correspondence.json으로 바꾼다(아래 JOBS 주석 참고).
# 창 10/20/30 µm, jitter 0.5 µm, 정렬 지름 5 µm는 권장 운용값(코드 기본값 아님)이다.
# 결과 local_delta.html이 쌍별 ΔCA 보기다. 통합 report는 아직 실자료(real_hotspot) compare 출력을 읽지 못해 회차에서 뺐다.
# 2회차의 comparison_masks.zip이 맞으면 재사용하고 없거나 입력이 바뀌었으면 다시 계산한다. 출력 폴더는 한 세대로 공개되며 죽은 뒤 다시 실행하면 복구한다.
# ============================== EDIT BELOW: 이 블록만 고치세요 ==============================
# 각 작업은 `python -m simcompare <명령> <인자...>`와 같다. 명령 이름은 import-hotspots, validate-data, compare,
# electrode-map, import-electrode-assets, export-review-rois, candidates-change, candidates, confirm-pairs, compare-windows, report 등이다.
# 인자는 명령줄에서 쓰던 그대로 문자열 리스트로 적는다. 상대 경로는 BASE_DIR 기준이다(아래). wrapper가 이 파일을 다른 곳에
# 복사해 실행하면 "이 .py가 있는 폴더"가 달라지므로, 상대 경로를 쓸 때는 BASE_DIR를 절대 경로로 적는 것이 안전하다.
# 작업은 위에서부터 차례로 실행된다. 종료 코드 0(완료)과 3(부분 결과)은 다음 작업으로 넘어가고, 그 밖의 코드는 멈춘다.
JOBS = [
    # 기본: 4회차 직접 대응. DL2 경로(5회차)를 썼다면 --correspondence 값을 data/confirmed/roi_correspondence.json으로 바꾼다
    ('compare-windows', [
        '--config', 'real.yaml',
        '--correspondence', 'data/changes/direct/roi_correspondence.json',
        '--window-sizes', '10',
        '20',
        '30',
        '--jitter-um', '0.5',
        '--sort-diameter-um', '5',
        '--out', 'data/local',
    ]),
]
LOG_FILE = 'runs/simcompare_6_compare_windows.log'   # stdout/stderr를 이 파일에도 남긴다. 필요 없으면 None
WORK_DIR = None                               # 패키지를 풀 폴더. None이면 이 파일 옆, 쓸 수 없으면 임시 폴더
BASE_DIR = None                               # JOBS·LOG_FILE·WORK_DIR의 상대 경로 기준 폴더(절대 경로). None이면 이 .py가 있는 폴더
# ============================== EDIT ABOVE ==============================================

